"""Local and S3 storage with the same three operations."""

from __future__ import annotations

import os
import tempfile
from pathlib import Path, PurePosixPath
from typing import Any, Protocol


class Store(Protocol):
    def exists(self, key: str) -> bool: ...
    def read(self, key: str) -> bytes: ...
    def write(self, key: str, content: bytes) -> None: ...


class LocalHansardStore:
    def __init__(self, data_root: str | Path = "data") -> None:
        self.data_root = Path(data_root)

    def _path(self, key: str) -> Path:
        # Keys are generated by pipeline.py, never taken from an HTTP request.
        return self.data_root.joinpath(*PurePosixPath(key).parts)

    def exists(self, key: str) -> bool:
        return self._path(key).is_file()

    def read(self, key: str) -> bytes:
        return self._path(key).read_bytes()

    def write(self, key: str, content: bytes) -> None:
        path = self._path(key)
        path.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile(dir=path.parent, delete=False) as handle:
            temporary = Path(handle.name)
            handle.write(content)
        try:
            os.replace(temporary, path)
        finally:
            temporary.unlink(missing_ok=True)


class S3HansardStore:
    """Use an injected Boto3 S3 client; creating this object makes no requests."""

    def __init__(self, client: Any, raw_bucket: str, processed_bucket: str) -> None:
        self.client = client
        self.raw_bucket = raw_bucket
        self.processed_bucket = processed_bucket

    def _bucket(self, key: str) -> str:
        if key.startswith("raw/"):
            return self.raw_bucket
        if key.startswith("processed/"):
            return self.processed_bucket
        raise ValueError(f"Unsupported storage key: {key}")

    def exists(self, key: str) -> bool:
        try:
            self.client.head_object(Bucket=self._bucket(key), Key=key)
        except Exception as error:
            # Permission/connection errors must never be interpreted as missing data.
            response = getattr(error, "response", {})
            code = str(response.get("Error", {}).get("Code", ""))
            status = response.get("ResponseMetadata", {}).get("HTTPStatusCode")
            if code in {"404", "NoSuchKey", "NotFound"} or (status == 404 and code != "NoSuchBucket"):
                return False
            raise
        return True

    def read(self, key: str) -> bytes:
        body = self.client.get_object(Bucket=self._bucket(key), Key=key)["Body"]
        try:
            return body.read()
        finally:
            body.close()

    def write(self, key: str, content: bytes) -> None:
        self.client.put_object(
            Bucket=self._bucket(key), Key=key, Body=content,
            ContentType="application/json; charset=utf-8",
        )
